// copyBreaking 复制破坏性条目切片（返回副本 ⇒ 消费方改不到包内状态）。
func copyBreaking(in []Breaking) []Breaking {
	if in == nil {
		return nil
	}
	out := make([]Breaking, len(in))
	copy(out, in)
	return out
}

